INSERT INTO setting (id, type, value, note) VALUES ('minions.tick_ticks', 'int', '20', 'Ticker period in server ticks (20 = once a second); only the animation and the status line depend on it.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.visual_range', 'int', '48', 'Blocks: a minion does real block work only while a player is closer than this.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.scan_seconds', 'int', '10', 'How often the surroundings of a minion nobody is looking at are re-checked.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.max_catchup_hours', 'int', '336', 'Longest offline / unloaded-chunk catch-up window (production is also capped by the storage).');
INSERT INTO setting (id, type, value, note) VALUES ('minions.island_check_seconds', 'int', '30', 'Island checks (reset, kicked from a co-op).');
INSERT INTO setting (id, type, value, note) VALUES ('minions.island_missing_hours', 'int', '6', 'A minion whose island has been gone this long is returned to its owner.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.member_collect', 'bool', 'false', 'Co-op members can also take items out of a minion''s storage.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.gui_click_millis', 'int', '150', 'Minimum time between two clicks in a minion menu.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.base_slots', 'int', '5', 'Minion slots: base + one per slot threshold reached by the number of different minions crafted.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.max_slots', 'int', '30', 'Most minion slots a player can have.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.slot_thresholds', 'list', '', 'Numbers of different minions (type + tier) crafted that each give one more slot.');
INSERT INTO setting_item (setting_id, position, value) VALUES ('minions.slot_thresholds', 0, '5');
INSERT INTO setting_item (setting_id, position, value) VALUES ('minions.slot_thresholds', 1, '15');
