INSERT INTO setting (id, type, value, note) VALUES ('minions.per_island_cap', 'int', '48', 'Hard limit of minions on one island, all players together.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.scale', 'real', '0.7', 'Size of the minion body (1.0 = player size).');
INSERT INTO setting (id, type, value, note) VALUES ('minions.compact_ratio', 'int', '160', 'Units of a resource needed for one compacted item.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.super_ratio', 'int', '160', 'Compacted items needed for one super compacted item.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.spread_every', 'int', '10', 'Diamond Spreading: one bonus diamond every N produced items.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.fuel_max_hours', 'int', '168', 'Most fuel a minion can hold, in hours.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.upgrade_slots', 'int', '2', 'Upgrade slots on every minion (fuel, skin and hat have their own slot).');
INSERT INTO setting (id, type, value, note) VALUES ('minions.fishing_min_water', 'int', '3', 'Minimum water blocks (layer under the minion) a Fishing Minion needs.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.chat_cooldown_seconds', 'int', '120', 'Chat message to the owner when a minion gets blocked, at most once per this many seconds.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.actions_per_cycle', 'int', '2', 'Actions in one cycle (one resource): place + break, plant + harvest, spawn + kill.');
INSERT INTO setting (id, type, value, note) VALUES ('minions.fishing_actions_per_cycle', 'int', '1', 'Fishing casts once per cycle.');
